+function loadSystem(index,initial=false){currentSystem=index;bodies=makeSystem(index);target=Math.max(0,bodies.findIndex(b=>b.type==='Terrestrial world'));player.x=0;player.y=0;player.z=0;player.yaw=0;player.pitch=0;player.speed=initial?240:95;updateHUD();renderMap();}
 function updateHUD(){let s=systems[currentSystem],b=bodies[target]||bodies[0];document.getElementById('systemName').textContent=s.tag+(currentSystem===0?' · Home system':'');document.getElementById('systemClass').textContent=s.cls;document.getElementById('bodyCount').textContent=bodies.length+' bodies';if(!b)return;document.getElementById('targetName').textContent=b.name;document.getElementById('targetType').textContent=b.type;document.getElementById('condition').textContent=b.condition;document.getElementById('gravity').textContent=b.gravity+' G';document.getElementById('scanStatus').textContent=b.discovered?'✓ LOGGED':'● SCANNED';document.getElementById('targetState').textContent=landing?'On surface':'In flight';document.getElementById('landButton').disabled=distance(b)>b.rad+95||player.speed>80;}
 function distance(b){return Math.hypot(b.x-player.x,b.y-player.y,b.z-player.z)}
 function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
 function renderMap(){let grid=document.getElementById('systemGrid');grid.innerHTML='';systems.forEach((s,i)=>{let btn=document.createElement('button');btn.className='system-option'+(i===currentSystem?' current':'');btn.innerHTML=`<span><b>${s.name}</b><small>${s.cls}</small></span><span class="count">${i===currentSystem?'CURRENT':'8 BODIES'}<small>${i===currentSystem?'':'FTL READY'}</small></span>`;btn.onclick=()=>beginWarp(i);grid.appendChild(btn)})}

