createStars();loadSystem(0,true);
const projected=[];
function cameraPoint(x,y,z){let dx=x-player.x,dy=y-player.y,dz=z-player.z,sy=Math.sin(player.yaw),cy=Math.cos(player.yaw),sp=Math.sin(player.pitch),cp=Math.cos(player.pitch);let right=dx*cy-dz*sy,up=-dx*sy*sp+dy*cp-dz*cy*sp,forward=dx*sy*cp+dy*sp+dz*cy*cp;let cr=Math.cos(player.roll),sr=Math.sin(player.roll);return {x:right*cr-up*sr,y:right*sr+up*cr,z:forward}}
function project(x,y,z){let p=cameraPoint(x,y,z);if(p.z<3)return null;let focal=Math.min(W,H)*.83,scale=focal/p.z;return {x:W*.5+p.x*scale,y:H*.5-p.y*scale,scale,depth:p.z}}
function drawBackground(dt){let g=ctx.createRadialGradient(W*.5,H*.48,0,W*.5,H*.48,Math.max(W,H)*.72);g.addColorStop(0,'#0e1a31');g.addColorStop(.52,'#080f20');g.addColorStop(1,'#03060e');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 let driftX=(player.yaw*110)%W,driftY=(player.pitch*105)%H;
 // distant nebula haze
 ctx.save();ctx.globalCompositeOperation='screen';let haze=ctx.createRadialGradient(W*.26+driftX*.4,H*.38+driftY*.4,2,W*.26+driftX*.4,H*.38+driftY*.4,Math.min(W,H)*.54);haze.addColorStop(0,'rgba(44,76,148,.105)');haze.addColorStop(.42,'rgba(50,45,115,.045)');haze.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=haze;ctx.fillRect(0,0,W,H);ctx.restore();
 for(let s of stars){let px=((s.x*W+driftX*(.12+s.z*.5))%W+W)%W,py=((s.y*H+driftY*(.12+s.z*.5))%H+H)%H,tw=.72+.28*Math.sin(now*.0018+s.t);ctx.globalAlpha=s.alpha*tw;ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(px,py,s.size*(.55+s.z*.45),0,TAU);ctx.fill();if(s.size>2){ctx.globalAlpha*=.25;ctx.fillRect(px-4,py,8,.6);ctx.fillRect(px,py-4,.6,8)}}ctx.globalAlpha=1;
}
function sphereColor(color,light){let c=color.replace('#','');let n=parseInt(c,16),r=n>>16,g=n>>8&255,b=n&255;return `rgb(${Math.min(255,r*light|0)},${Math.min(255,g*light|0)},${Math.min(255,b*light|0)})`}
function drawPlanet(body,p,idx){let rr=Math.max(2,body.rad*p.scale),s=Math.max(1,rr);if(rr<1.2)return;let cx=p.x,cy=p.y;ctx.save();ctx.globalAlpha=1;
 if(body.type==='Black hole'||body.type==='Anomaly'){let glow=ctx.createRadialGradient(cx,cy,s*.4,cx,cy,s*2.7);glow.addColorStop(0,'rgba(80,48,153,.65)');glow.addColorStop(.3,'rgba(136,77,245,.25)');glow.addColorStop(1,'rgba(84,40,164,0)');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(cx,cy,s*2.7,0,TAU);ctx.fill();ctx.strokeStyle='#e2b9ff';ctx.lineWidth=Math.max(1,s*.11);ctx.beginPath();ctx.ellipse(cx,cy,s*1.65,s*.47,-.25,0,TAU);ctx.stroke();ctx.globalAlpha=.9;ctx.fillStyle='#02020a';ctx.beginPath();ctx.arc(cx,cy,s*.61,0,TAU);ctx.fill();ctx.strokeStyle='#a575ff';ctx.lineWidth=Math.max(1,s*.035);ctx.beginPath();ctx.arc(cx,cy,s*.7,0,TAU);ctx.stroke();}
 else if(body.type==='Nebula'){let neb=ctx.createRadialGradient(cx-s*.22,cy-s*.15,0,cx,cy,s);neb.addColorStop(0,'#ffc6ed');neb.addColorStop(.25,'#d58aff');neb.addColorStop(.62,'#7655cb88');neb.addColorStop(1,'#5d64be00');ctx.fillStyle=neb;ctx.beginPath();ctx.arc(cx,cy,s,0,TAU);ctx.fill();}
 else {if(body.type.includes('Ring')){ctx.save();ctx.translate(cx,cy);ctx.rotate(-.25);ctx.strokeStyle='#e5c99499';for(let i=0;i<5;i++){ctx.lineWidth=Math.max(1,s*.06);ctx.beginPath();ctx.ellipse(0,0,s*(1.3+i*.16),s*(.35+i*.035),0,0,TAU);ctx.stroke()}ctx.restore()}
 let glow=ctx.createRadialGradient(cx,cy,s*.2,cx,cy,s*1.4);glow.addColorStop(0,body.type.includes('star')?'#fff5cf88':'#72cbff25');glow.addColorStop(1,'transparent');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(cx,cy,s*1.4,0,TAU);ctx.fill();let grad=ctx.createRadialGradient(cx-s*.34,cy-s*.37,s*.04,cx+s*.2,cy+s*.12,s*1.12);grad.addColorStop(0,body.type.includes('star')?'#fff7dd':sphereColor(body.color,1.42));grad.addColorStop(.55,body.color);grad.addColorStop(1,'#060914');ctx.fillStyle=grad;ctx.beginPath();ctx.arc(cx,cy,s,0,TAU);ctx.fill();ctx.save();ctx.beginPath();ctx.arc(cx,cy,s,0,TAU);ctx.clip();ctx.globalAlpha=.14;ctx.strokeStyle='#ecf7ff';ctx.lineWidth=Math.max(1,s*.09);for(let n=-2;n<3;n++){ctx.beginPath();ctx.ellipse(cx+s*.15,cy+s*n*.28,s*1.1,s*.18,body.seed+n*.2,0,TAU);ctx.stroke()}ctx.restore();if(body.type.includes('star')){ctx.globalAlpha=.9;let glow2=ctx.createRadialGradient(cx,cy,s*.25,cx,cy,s*1.6);glow2.addColorStop(0,'#fff8df55');glow2.addColorStop(1,'transparent');ctx.fillStyle=glow2;ctx.beginPath();ctx.arc(cx,cy,s*1.6,0,TAU);ctx.fill()}}
 if(idx===target){ctx.globalAlpha=.8;ctx.strokeStyle='#68e7ff';ctx.lineWidth=1;ctx.setLineDash([5,5]);ctx.beginPath();ctx.arc(cx,cy,s+9,0,TAU);ctx.stroke();ctx.setLineDash([]);let d=distance(body);if(d<body.rad+280){ctx.font='10px "DM Mono",monospace';ctx.fillStyle='#b9f5ff';ctx.textAlign='center';ctx.fillText(body.name.toUpperCase(),cx,cy-s-17);ctx.fillStyle='#81acc8';ctx.fillText(Math.round(d)+' KM',cx,cy-s-4)}}
 ctx.restore();}
function drawScene(dt){drawBackground(dt);projected.length=0;let items=bodies.map((b,i)=>({b,i,p:project(b.x,b.y,b.z)})).filter(o=>o.p&&o.p.depth<9000).sort((a,b)=>b.p.depth-a.p.depth);for(let o of items){drawPlanet(o.b,o.p,o.i);projected.push(o)}drawRadar();drawSpeed();if(warp>0){ctx.save();ctx.fillStyle=`rgba(157,219,255,${Math.min(.62,warp*.34)})`;ctx.fillRect(0,0,W,H);ctx.strokeStyle='#b6eeff99';for(let i=0;i<55;i++){let x=Math.random()*W,y=Math.random()*H;ctx.globalAlpha=Math.random()*.6;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(W/2+(x-W/2)*1.3,H/2+(y-H/2)*1.3);ctx.stroke()}ctx.restore()}}

