function drawScene(dt){drawBackground(dt);projected.length=0;let items=bodies.map((b,i)=>({b,i,p:project(b.x,b.y,b.z)})).filter(o=>o.p&&o.p.depth<9000).sort((a,b)=>b.p.depth-a.p.depth);for(let o of items){drawPlanet(o.b,o.p,o.i);projected.push(o)}drawRadar();drawSpeed();if(warp>0){ctx.save();ctx.fillStyle=`rgba(157,219,255,${Math.min(.62,warp*.34)})`;ctx.fillRect(0,0,W,H);ctx.strokeStyle='#b6eeff99';for(let i=0;i<55;i++){let x=Math.random()*W,y=Math.random()*H;ctx.globalAlpha=Math.random()*.6;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(W/2+(x-W/2)*1.3,H/2+(y-H/2)*1.3);ctx.stroke()}ctx.restore()}}
function drawRadar(){let r=radar.getBoundingClientRect(),w=r.width,h=r.height,cx=w/2,cy=h/2,rad=Math.min(w,h)*.43;rctx.clearRect(0,0,w,h);rctx.save();rctx.strokeStyle='rgba(111,173,221,.18)';rctx.lineWidth=1;for(let k=1;k<=3;k++){rctx.beginPath();rctx.arc(cx,cy,rad*k/3,0,TAU);rctx.stroke()}rctx.beginPath();rctx.moveTo(cx,cy-rad);rctx.lineTo(cx,cy+rad);rctx.moveTo(cx-rad,cy);rctx.lineTo(cx+rad,cy);rctx.stroke();rctx.fillStyle='#73f3ff';rctx.beginPath();rctx.moveTo(cx,cy-5);rctx.lineTo(cx-4,cy+4);rctx.lineTo(cx+4,cy+4);rctx.closePath();rctx.fill();let span=2400;for(let i=0;i<bodies.length;i++){let b=bodies[i],dx=b.x-player.x,dz=b.z-player.z,sy=Math.sin(player.yaw),cyaw=Math.cos(player.yaw),rx=dx*cyaw-dz*sy,rz=dx*sy+dz*cyaw,px=cx+rx/span*rad,py=cy-rz/span*rad;if(Math.hypot(px-cx,py-cy)>rad)continue;rctx.fillStyle=i===target?'#7ceaff':b.type.includes('star')||b.type==='Black hole'?'#ffcf80':'#90a9cc';rctx.beginPath();rctx.arc(px,py,i===target?3:2,0,TAU);rctx.fill()}rctx.restore()}
function drawSpeed(){let s=player.speed;document.getElementById('speedValue').textContent=Math.round(s);document.getElementById('speedMeter').style.width=(s/player.maxSpeed*100)+'%';document.getElementById('throttleLabel').textContent=Math.round(s/player.maxSpeed*100)+'% THRUST';let b=bodies[target];if(b){document.getElementById('rangeValue').textContent=Math.round(distance(b))+' km';document.getElementById('landButton').disabled=distance(b)>b.rad+95||s>80||landing}}
function tick(t){let dt=Math.min(.05,(t-last)/1000||.016);last=t;now=t;if(!landing&&warp<=0){let turn=1.35*dt;if(keys.has('a')||keys.has('arrowleft'))player.yaw-=turn;if(keys.has('d')||keys.has('arrowright'))player.yaw+=turn;if(keys.has('w')||keys.has('arrowup'))player.pitch=clamp(player.pitch+turn,-1.45,1.45);if(keys.has('s')||keys.has('arrowdown'))player.pitch=clamp(player.pitch-turn,-1.45,1.45);if(keys.has('q'))player.roll-=turn;if(keys.has('e'))player.roll+=turn;if(keys.has('shift'))player.speed=Math.min(player.maxSpeed,player.speed+520*dt);else if(keys.has('control')||keys.has(' '))player.speed=Math.max(0,player.speed-760*dt);else player.speed=Math.max(35,player.speed-8*dt);let sy=Math.sin(player.yaw),cy=Math.cos(player.yaw),sp=Math.sin(player.pitch),cp=Math.cos(player.pitch);let step=player.speed*dt;player.x+=sy*cp*step;player.y+=sp*step;player.z+=cy*cp*step;}
 if(warp>0){warp-=dt;if(warp<=0){loadSystem(warpTarget);toast('ARRIVED · '+systems[currentSystem].name.toUpperCase()+' SYSTEM')}}drawScene(dt);if(t%140<17)updateHUD();requestAnimationFrame(tick)}
function doLand(){if(landing)return;let b=bodies[target];if(!b)return;if(distance(b)>b.rad+95){toast('APPROACH CLOSER · '+Math.round(distance(b)-b.rad)+' KM OUT');return}if(player.speed>80){toast('REDUCE VELOCITY BELOW 80 KM/S');return}startLanding()}
function cycleTarget(dir=1){target=(target+dir+bodies.length)%bodies.length;updateHUD();toast('TARGET LOCKED · '+bodies[target].name.toUpperCase())}
function keyDown(e){let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(!keys.has(k)){if(k==='m')openMap();if(k==='f'||k==='enter')doLand();if(k==='tab'){e.preventDefault();cycleTarget(1)}if(k==='escape'){document.getElementById('modal').classList.remove('open');if(landing)launch()}}keys.add(k)}
function keyUp(e){keys.delete(e.key.toLowerCase())}
addEventListener('keydown',keyDown);addEventListener('keyup',keyUp);addEventListener('blur',()=>keys.clear());
canvas.addEventListener('click',e=>{let best=null,bd=Infinity;for(let o of projected){let d=Math.hypot(e.clientX-o.p.x,e.clientY-o.p.y),r=Math.max(17,o.b.rad*o.p.scale*1.5);if(d<r&&d<bd){bd=d;best=o.i}}if(best!==null)chooseTarget(best);else if(target>=0)doLand()});
canvas.addEventListener('pointerdown',e=>{mouse.down=true;mouse.x=e.clientX;mouse.y=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(mouse.down&&e.pointerType==='mouse'&&e.buttons===1){let dx=e.clientX-mouse.x,dy=e.clientY-mouse.y;player.yaw+=dx*.003;player.pitch=clamp(player.pitch-dy*.003,-1.45,1.45)}mouse.x=e.clientX;mouse.y=e.clientY});canvas.addEventListener('pointerup',()=>mouse.down=false);canvas.addEventListener('wheel',e=>cycleTarget(e.deltaY>0?1:-1),{passive:true});
document.getElementById('landButton').onclick=doLand;document.getElementById('launchButton').onclick=launch;document.getElementById('mapButton').onclick=openMap;document.getElementById('landMapButton').onclick=()=>{document.getElementById('landScreen').classList.remove('show');landing=false;openMap()};document.getElementById('closeMap').onclick=()=>document.getElementById('modal').classList.remove('open');document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')e.currentTarget.classList.remove('open')});
document.querySelectorAll('.touch-btn[data-key]').forEach(btn=>{let k=btn.dataset.key;for(let event of ['pointerdown','pointerup','pointercancel','pointerleave'])btn.addEventListener(event,e=>{e.preventDefault();if(event==='pointerdown'){keys.add(k);btn.classList.add('down')}else{keys.delete(k);btn.classList.remove('down')}})});requestAnimationFrame(tick);
</script>
</body>
</html>

